use super::*;
use std::{path::Path,process::Command};
fn git(root:&Path,args:&[&str])->String{let out=Command::new("git").current_dir(root).args(args).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));String::from_utf8(out.stdout).unwrap().trim().into()}
#[test] fn exact_ref_cas_preserves_successor(){let dir=tempfile::tempdir().unwrap();git(dir.path(),&["init","-q"]);git(dir.path(),&["-c","user.name=Task","-c","user.email=task@local","commit","--allow-empty","-qm","one"]);let one=git(dir.path(),&["rev-parse","HEAD"]);git(dir.path(),&["-c","user.name=Task","-c","user.email=task@local","commit","--allow-empty","-qm","two"]);let two=git(dir.path(),&["rev-parse","HEAD"]);let repo=git::GitRepo::require(dir.path()).unwrap();let name="refs/heads/task-cas";assert!(repo.compare_and_swap_ref(name,None,Some(&one)).unwrap());assert!(repo.compare_and_swap_ref(name,Some(&one),Some(&two)).unwrap());assert!(!repo.compare_and_swap_ref(name,Some(&one),Some(&one)).unwrap());assert_eq!(repo.resolve_ref(name).unwrap(),Some(two.clone()));assert!(!repo.compare_and_swap_ref(name,Some(&one),None).unwrap());assert!(repo.compare_and_swap_ref(name,Some(&two),None).unwrap());}
#[test] fn pure_jj_nearest_root_and_colocated(){let dir=tempfile::tempdir().unwrap();std::fs::create_dir_all(dir.path().join(".jj/repo")).unwrap();assert!(is_pure_jj(dir.path()).unwrap());git(dir.path(),&["init","-q"]);assert!(!is_pure_jj(dir.path()).unwrap());let deep=dir.path().join("deep");std::fs::create_dir_all(deep.join(".jj/repo")).unwrap();assert!(is_pure_jj(&deep).unwrap());git(&deep,&["init","-q"]);assert!(!is_pure_jj(&deep).unwrap());}
